use std::{env,fs,path::Path};
use wasmc::lib_tool_rust_consumer_sdk::native_build::{NativePinnedFile,host::{compile_host_canonical_source,HostContract,HostContractPair}};
fn sha(b:&[u8])->String{wasmc::self_bundle::hex(&wasmc::self_bundle::sha256(b))}
fn contract(dir:&Path,selection:&[&str])->HostContract{let f=|n|fs::read(dir.join(n)).unwrap();let (wit,execution_abi,provider_contract,binding)=(f("lib.wit"),f("execution-abi.json"),f("provider-contract.json"),f("binding.json"));HostContract{schema:"wasmc.canonical-host-contract/v1".into(),wit_sha256:sha(&wit),execution_abi_sha256:sha(&execution_abi),provider_contract_sha256:sha(&provider_contract),binding_sha256:sha(&binding),wit,execution_abi,provider_contract,binding,selected_operations:vec![],operation_selection:Some(selection.iter().map(|x|x.to_string()).collect())}}
fn main(){let a:Vec<String>=env::args().collect();let root=Path::new(&a[1]);let hostroot=Path::new(&a[2]);let out=Path::new(&a[3]);let source=fs::read_to_string(&a[4]).unwrap();let host=HostContractPair{entry:contract(&hostroot.join("entry"),&[]),operations:contract(&hostroot.join("operations"),&if a[5].is_empty(){Vec::new()}else{a[5].split(',').collect::<Vec<_>>()})};let pin=sha(&fs::read(root.join("lib.json")).unwrap());let app=compile_host_canonical_source(&source,root,&pin,&host,17).expect("compile host");if a.len()==6{fs::write(out.join("transfer.rs"),app.transfer_source).unwrap();}else{let transfer=Path::new(&a[6]);let p=NativePinnedFile{path:transfer.into(),sha256:sha(&fs::read(transfer).unwrap())};app.prepare_merge_assets(&host,&p,&out.join("prepared")).expect("prepare");}}
